// One operation, one call site, no Android imports
class PlaceOrder @Inject constructor(
  private val cart: CartRepository,
  private val orders: OrderRepository,
  private val pricing: PricingRepository
) {
  suspend operator fun invoke(address: Address): Result<OrderId> {
    val items = cart.items()
    if (items.isEmpty()) return Result.failure(EmptyCart)

    val quote = pricing.quote(items, address)          // a rule owned by no single repo
    if (quote.exceedsLimit) return Result.failure(OverLimit(quote.limit))

    return orders.place(items, address, quote).onSuccess { cart.clear() }
  }
}

