sealed interface EditorEvent {
  data class Saved(val id: Long) : EditorEvent
  data class Failed(val message: String) : EditorEvent
}

class EditorViewModel @Inject constructor(private val repo: NoteRepo) : ViewModel() {
  private val _events = Channel<EditorEvent>(Channel.BUFFERED)   // not replayed, not dropped
  val events = _events.receiveAsFlow()

  fun save(draft: Draft) = viewModelScope.launch {
    _state.update { it.copy(isSaving = true) }
    repo.save(draft)
      .onSuccess { _events.send(EditorEvent.Saved(it)) }
      .onFailure { _events.send(EditorEvent.Failed("Could not save")) }
    _state.update { it.copy(isSaving = false) }
  }
}

@Composable
fun EditorScreen(
  vm: EditorViewModel,
  snackbar: SnackbarHostState,
  onNavigateBack: () -> Unit          // the SCREEN owns navigation, not the ViewModel
) {
  val lifecycle = LocalLifecycleOwner.current.lifecycle
  LaunchedEffect(vm, lifecycle) {
    lifecycle.repeatOnLifecycle(Lifecycle.State.STARTED) {
      vm.events.collect { event ->
        when (event) {
          is EditorEvent.Saved -> onNavigateBack()
          is EditorEvent.Failed -> {
            val result = snackbar.showSnackbar(event.message, actionLabel = "Retry")
            if (result == SnackbarResult.ActionPerformed) vm.retry()
          }
        }
      }
    }
  }
}

