sealed interface DataError {
  data object Offline : DataError
  data object Unauthorized : DataError
  data class Invalid(val fields: List<String>) : DataError
  data class Unexpected(val cause: Throwable) : DataError
}

sealed interface Outcome<out T> {
  data class Success<T>(val value: T) : Outcome<T>
  data class Failure(val error: DataError) : Outcome<Nothing>
}

// one place that knows about Retrofit — and it never eats cancellation
private suspend fun <T> apiCall(block: suspend () -> T): Outcome<T> = try {
  Outcome.Success(block())
} catch (e: CancellationException) {
  throw e                                   // structured concurrency stays intact
} catch (e: IOException) {
  Outcome.Failure(DataError.Offline)
} catch (e: HttpException) {
  Outcome.Failure(
    when (e.code()) {
      401 -> DataError.Unauthorized
      422 -> DataError.Invalid(e.parseFieldErrors())
      else -> DataError.Unexpected(e)
    }
  )
}

