  navigation<CheckoutGraph>(startDestination = Cart) {
    composable<Cart> { entry ->
      CartScreen(entry.checkoutViewModel(nav), onNext = { nav.navigate(Shipping) })
    }
    composable<Shipping> { entry ->
      ShippingScreen(entry.checkoutViewModel(nav), onNext = { nav.navigate(Payment) })
    }
    composable<Payment> { entry ->
      PaymentScreen(
        vm = entry.checkoutViewModel(nav),
        onDone = {
          // inclusive: the graph entry leaves the stack, so onCleared() runs
          nav.navigate(Home) { popUpTo<CheckoutGraph> { inclusive = true } }
        }
      )
    }
  }
}

