class MainDispatcherRule(
  private val dispatcher: TestDispatcher = UnconfinedTestDispatcher()
) : TestWatcher() {
  override fun starting(description: Description) = Dispatchers.setMain(dispatcher)
  override fun finished(description: Description) = Dispatchers.resetMain()
}

class OrdersViewModelTest {
  @get:Rule val mainDispatcherRule = MainDispatcherRule()

  // ❌ always Loading: viewModelScope has not run, and nobody subscribed to the StateFlow
  @Test fun broken() = runTest {
    val vm = OrdersViewModel(FakeOrderRepository(orders))
    vm.load()
    assertEquals(Loading, vm.state.value)
  }

  @Test fun `emits orders once loaded`() = runTest {
    val vm = OrdersViewModel(FakeOrderRepository(orders))

    vm.state.test {                                  // Turbine is the collector
      assertEquals(Loading, awaitItem())
      vm.load()
      assertEquals(Loaded(orders), awaitItem())
      cancelAndIgnoreRemainingEvents()
    }
  }

  // the alternative when you want plain assertions: subscribe, then drain the scheduler
  @Test fun `starts the upstream`() = runTest {
    val vm = OrdersViewModel(FakeOrderRepository(orders))
    backgroundScope.launch(UnconfinedTestDispatcher(testScheduler)) { vm.state.collect() }

    vm.load()
    advanceUntilIdle()
    assertEquals(Loaded(orders), vm.state.value)
  }
}

