// data layer: Room generates the PagingSource; the DTO never leaves this file
@Dao interface ItemDao {
  @Query("SELECT * FROM items WHERE category = :category ORDER BY rank")
  fun pagingSource(category: String): PagingSource<Int, ItemEntity>
}

class ItemRepository @Inject constructor(private val dao: ItemDao, private val mediator: ItemMediator) {
  @OptIn(ExperimentalPagingApi::class)
  fun items(category: String): Flow<PagingData<Item>> = Pager(
    config = PagingConfig(pageSize = 20, enablePlaceholders = false),
    remoteMediator = mediator,
    pagingSourceFactory = { dao.pagingSource(category) }
  ).flow.map { page -> page.map(ItemEntity::toDomain) }   // mapped BEFORE caching
}

@HiltViewModel
class CatalogViewModel @Inject constructor(repo: ItemRepository) : ViewModel() {
  private val category = MutableStateFlow("all")

  // a filter change builds a new Pager; cachedIn is last, so rotation replays the pages
  val items: Flow<PagingData<Item>> = category
    .flatMapLatest { repo.items(it) }
    .cachedIn(viewModelScope)

  fun select(value: String) { category.value = value }
}

@Composable
fun CatalogScreen(vm: CatalogViewModel) {
  val items = vm.items.collectAsLazyPagingItems()
  LazyColumn {
    items(items.itemCount, key = items.itemKey { it.id }) { index ->
      items[index]?.let { ItemRow(it) }
    }
    if (items.loadState.append is LoadState.Loading) item { ProgressRow() }
  }
}

